"""
PAL Cross Encoder inside SAP HANA

    * :class:`PALCrossEncoder`
"""

#pylint: disable=redefined-builtin
#pylint: disable=bare-except
import uuid
import logging
from hdbcli import dbapi
from hana_ml.algorithms.pal.pal_base import (
    PALBase,
    ParameterTable,
    arg,
    try_drop
)

logger = logging.getLogger(__name__)#pylint: disable=invalid-name

class PALCrossEncoder(PALBase):
    """
    PALCrossEncoder processeses paired inputs, like (query, document) pairs together to determine their relationship or similarity,
    outputting their relevance scores. Unlike bi-encoders, which encode inputs separately into vectors,
    cross encoders analyze the interaction between the input pair simultaneously, allowing for precise
    semantic understanding and high-accuracy results, particularly in re-ranking tasks within information retrieval.

    Parameters
    ----------
    model_version : str, optional
        Specifies the version of SAP PAL cross-encoder model to use.

        Currently the only valid version is 'SAP_CER.20250701'.

        Defaults to None (currently uses 'SAP_CER.20250701' by default).

    max_token_num : int, optional
        The maximum number of tokens allowed for the input of cross-encoder model.

        The default value and value range depend on the model.
        See `Cross Encoder Model<https://help.sap.com/docs/hana-cloud-database/sap-hana-cloud-sap-hana-database-predictive-analysis-library/cross-encoder-model?locale=en-US&state=DRAFT&version=2026_1_QRC>`_ for detailed information.

    Attributes
    ----------
    model_version : str
        The version of the cross-encoder model associated with the PALCrossEncoder instance.

    max_token_num : int
        The maximum number of tokens allowed for the input of cross-encoder model associated with
        the PALCrossEncoder instance.

    Examples
    --------
    Suppose you have a HANA DataFrame `df` with ID column 'ID', content columns 'QUERY' and 'DOC'.
    To compute the relevant scores of pairs in 'QUERY' and 'DOC' bonding with the same IDs,
    we can create a PALCrossEncoder instance and call its `fit_predict()` method:

    >>> from hana_ml.text.pal_cross_encoder import PALCrossEncoder
    >>> ce_model = PALCrossEncoder(model_version='SAP_CER.20250701')
    >>> result = ce_model.fit_predict(data=df, key='ID', target=['QUERY', 'DOC'])
    >>> # The result is a DataFrame containing the relevant scores of paird inputs
    >>> print(result.collect())
    """
    def __init__(self, model_version=None,
                 max_token_num=None):
        super(PALCrossEncoder, self).__init__()
        self.connection_context = None
        self.model_version = arg('model_version', model_version, str)
        self.max_token_num = arg('max_token_num', max_token_num, int)
        self.stats_ = None

    def predict(self, data, #pylint: disable=too-many-positional-arguments
                key,
                content,
                thread_number=None,
                batch_size=None,
                max_token_num=None,
                return_table=False):
        r"""
        Calculate the relevance scores for pairs inputs using cross-encoder model.

        Parameters
        ----------
        data: DataFrame
            Input data containing the paired inputs for relevance score calculation.
        key: str
            Name of the key (ID) column.
        target: list/tuple of str
            Names of the two columns that contain the pairs for relevance score calculation.
        thread_number: int, optional
            Specifies the number of HTTP connections that are established simultaneously to the backend cross encoder service.
            The valid range is from 1 to 10.

            Defaults to 6.
        batch_size: int, optional
            Specifies the number of pairs grouped into a single request before sending to the cross encoder service.

            The value range is from 1 to 50.

            Defaults to 10.
        max_token_num: int, optional
            The maximum number of tokens allowed for the input of cross-encoder model.

            If ``max_token_num`` is None, the value in self.max_token_num will be used.

            Defaults to None.

        return_table : bool, optional
            Specifies whether to return the DataFrame of the result or not.

            If set as False, numpy array of the relevance scores shall be returned instead.

            Default to False.

        Returns
        -------
        DataFrame
            DataFrame containing the relevances scores, together with additional messages related
            to the resulting scores.

        DataFrame
            Other related statistics.
        """
        conn = data.connection_context
        self.connection_context = conn
        unique_id = str(uuid.uuid1()).replace('-', '_').upper()
        tables = ["RESULT", "STATS"]
        outputs = [f'#PAL_CROSS_ENCODER_{tab}_TBL_{unique_id}' for tab in tables]
        param_rows = [("BATCH_SIZE", batch_size, None, None),
                      ("MODEL_VERSION", None, None, self.model_version),
                      ("THREAD_NUMBER", thread_number, None, None),
                      ("MAX_TOKEN_NUM", max_token_num if max_token_num else self.max_token_num, None, None)]
        data_ = data[[key] + list(content)]
        try:
            self._call_pal_auto(conn,
                                'PAL_CROSSENCODER',
                                data_,
                                ParameterTable().with_data(param_rows),
                                *outputs)
        except dbapi.Error as db_err:
            msg = str(conn.hana_version())
            logger.exception("HANA version: %s. %s", msg, str(db_err))
            try_drop(conn, outputs)
            raise
        except Exception as db_err:
            logger.exception(str(db_err))
            try_drop(conn, outputs)
            raise
        self.stats_ = conn.table(outputs[1])
        result = conn.table(outputs[0])
        if not return_table:
            result_df = result.collect()
            try_drop(self.connection_context, outputs[0])
            # sort result_df by id
            result_df = result_df.sort_values(by=result_df.columns[0])
            # return score column as ndarray
            return result_df[result_df.columns[1]].to_numpy()
        return result
